// 变量、可变性、遮蔽与常量 完整演示（可直接 rustc 运行）
fn main() {
    // 1. 默认不可变：下面这行如果取消注释会编译失败
    // error[E0384]: cannot assign twice to immutable variable `max_retry`
    let max_retry = 3;
    // max_retry = 5;
    println!("1) max_retry = {}", max_retry);

    // 2. mut 显式可变：状态会随时间变化的计数器
    let mut counter = 0;
    counter += 1;
    counter += 1;
    println!("2) counter = {}", counter);

    // 3. Shadowing：变量名不变，但每一步「加工」都新建绑定，甚至可以换类型
    let input = "  42  ";          // &str
    let input = input.trim();      // &str（去掉首尾空白）
    let input: i32 = input.parse().expect("数字解析失败"); // i32（类型变了！）
    println!("3) 解析后的数字 + 8 = {}", input + 8);

    // 4. const 常量：必须标注类型，编译期求值，SCREAMING_SNAKE_CASE
    const MAX_POINTS: u32 = 100_000;
    println!("4) MAX_POINTS = {}", MAX_POINTS);

    // 5. 作用域与遮蔽：内部 let 只在花括号块内生效
    let price = 100;
    println!("5) 块外 price = {}", price);
    {
        let price = price * 2; // 遮蔽外层的 price
        println!("   块内 price = {}", price);
    }
    println!("   回到块外 price = {}", price);

    // 6. 未使用的 mut 会被编译器警告：unused_mut
    let mut unnecessary_mut = 42;
    unnecessary_mut = 43; // 这里确实用到了 mut
    println!("6) unnecessary_mut = {}", unnecessary_mut);
}

